import { useCallback, useEffect, useState, useRef } from 'react'
import { CriteriaPageStyle, ConfirmationContainer, Footer } from './index.style'
import { Container, CustomText, Button } from '../../../../../../components'
import { LANG_STRINGS } from '../../../../../../lang/index'
import { useGetVehicleYear, useGetVehicleBrand, useGetVehicleVariant, useCreateDraftQuote } from '../../../state/hooks/useExtendedWarrantyState'
import StatusInfoCard from '../../../../../../components/StatusInfoCard'
import AutoSearchBottomSheet from '../../../../../../components/DynamicForm/components/AutoSearchBottomSheet'
import CircularLoader from '../../../../../../components/CircularLoader'
import BottomActionSheet from '../../../../../../components/BottomActionSheet'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { Row } from '../../../../../../commonStyle/index.style'
import { useLoaderContextValue, useErrorContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import PolicyStepsHeader from '../../../../../../components/PolicyStepsHeader'
import { STEPS } from '../../../constant'
import { getErrorMessage } from '../../../../../../helpers/utility'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import { useHistory } from 'react-router-dom'
import moment from 'moment'
import { INFORMATION_NEW } from '../../../../../../images/imageUrl'

function CriteriaPage () {
  const history = useHistory()
  const [{ getVehicleYearData = [] }, getVehicleYearReq] = useGetVehicleYear()
  const [{ getVehicleBrandData = [] }, getVehicleBrandReq] = useGetVehicleBrand()
  const [{ getVehicleVariantData = [] }, getVehicleVariantReq] = useGetVehicleVariant()
  const [{ createDraftQuotationData = {} }, createDraftQuoteReq] = useCreateDraftQuote()
  const [{ GET_VEHICLE_YEAR_LOADER }] = useLoaderContextValue()
  const [{ createDraftQuotationStatus, createDraftQuotationErrorData }] = useErrorContextValue()
  const { resetError } = useResetError()
  const autoSearchRef = useRef(null)
  const autoSearchBrandRef = useRef(null)
  const autoSearchModelRef = useRef(null)
  const [formValues, setFormValues] = useState({ year: '', brand_data: {}, model_data: {} })
  const [showConfirmation, setShowConfirmation] = useState(false)

  useEffect(() => {
    if (createDraftQuotationStatus === 'success') {
      if (createDraftQuotationData?.draft_id) {
        // insert next page url here
        history.push(`/extended_warranty/insured_package/${createDraftQuotationData?.draft_id}`)
      }
      resetError(['createDraftQuotationStatus'])
    }
    if (createDraftQuotationErrorData) {
      ShowSnackbar.error({
        visible: true,
        text: getErrorMessage(500)
      })
      resetError(['createDraftQuotationErrorData'])
    }
  }, [createDraftQuotationData, createDraftQuotationStatus, createDraftQuotationErrorData, resetError, history])

  const handleBackButton = useCallback(() => {
    history.push('/dashboard')
  }, [history])

  const handleBrandChange = (value) => {
    setFormValues(formValues => ({ ...formValues, brand_data: value }))
    if (value) {
      getVehicleVariantReq({
        params: {
          brand: value.code,
          year: formValues.year
        },
        query: {
          category: 'NON_TRUCK_NON_BUS',
          package_type: 'car-protection-comprehensive'
        }
      })
    }
    if (autoSearchModelRef.current) {
      autoSearchModelRef.current.resetSearch('model')
      setFormValues(formValues => ({ ...formValues, model_data: {} }))
    }
  }

  const handleModelChange = (value) => {
    setFormValues(formValues => ({ ...formValues, model_data: value }))
  }

  const handleSubmit = () => {
    const payload = {
      section: 'protection_type',
      sub_section: 'vehicle_criteria',
      data: {
        ...formValues,
        model: formValues.model_data.model_code,
        vehicle_sum_insured: formValues.model_data.price,
        brand: formValues.brand_data.code,
        vehicle_type: 'non-bus-non-truck',
        usage: 'Personal',
        package_type: 'car-protection-comprehensive',
        product_code: 'extended-warranty-protection',
        start_date: moment().format('YYYY-MM-DD'),
        variant: formValues.model_data.variant_name,
        variant_code: formValues.model_data.variant_code
      }
    }
    createDraftQuoteReq({
      body: payload
    })
  }

  useEffect(() => {
    getVehicleYearReq({
      query: {
        code: 'extended-warranty-protection',
      }
    })
  }, [getVehicleYearReq])

  return (
    <Container
      title={LANG_STRINGS.extendedWarranty}
      showinnerHeader
      onClose={() => history.replace('/dashboard')}
      showCloseIcon
      displayBackButton
      hideBottomTabs
      onBackClick={handleBackButton}
    >
      <CircularLoader
        isLoading={GET_VEHICLE_YEAR_LOADER}
      >
        <PolicyStepsHeader
          stepsData={STEPS}
          activeCount={1}
        />
        <CriteriaPageStyle>
          <Row align='center' justify='space-between'>
            <CustomText
              size='15px'
              color={AgentColorPallette.regular}
              weight={700}
              top='50px'
              bottom='20px'
            >
              Kategori Kendaraan
            </CustomText>
          </Row>
          <StatusInfoCard
            info={
              <span>
                <div className='info-text'>Hanya berlaku untuk kategori penggunaan: </div>
                <div className='info-text'> <span className='blue-text'>Personal / Operasional Kantor </span> dengan jenis kendaraan : <span className='blue-text'>Mobil Penumpang</span> </div>
              </span>
            }
            bgColor='#FFFFFF'
          />
          <Row align='center' justify='space-between'>
            <CustomText
              size='15px'
              color={AgentColorPallette.regular}
              weight={700}
              top='20px'
              bottom='20px'
            >
              Detail Kendaraan
            </CustomText>
          </Row>
          <div>
            <AutoSearchBottomSheet
              title='Tahun Kendaraan'
              name='year'
              data={getVehicleYearData}
              displayKey='year'
              dataKey='year'
              isBoxWithoutIcon
              showHeader
              required
              headerTitle='Tahun Kendaraan'
              designV2
              onChange={(value) => {
                setFormValues(formValues => ({ ...formValues, year: value.year }))
                getVehicleBrandReq({
                  year: value.year,
                  query: {
                    category: 'NON_TRUCK_NON_BUS',
                    package_type: 'car-protection-comprehensive'
                  }
                })
                if (autoSearchBrandRef.current) {
                  autoSearchBrandRef.current.resetSearch('brand')
                  setFormValues(formValues => ({ ...formValues, brand_data: {} }))
                }
                if (autoSearchModelRef.current) {
                  autoSearchModelRef.current.resetSearch('model')
                  setFormValues(formValues => ({ ...formValues, model_data: {} }))
                }
              }}
              ref={autoSearchRef}
            />
            <AutoSearchBottomSheet
              title='Merk Kendaraan'
              name='brand'
              data={getVehicleBrandData}
              displayKey='name'
              dataKey='code'
              isIconWithBox
              showHeader
              required
              headerTitle='Merk Kendaraan'
              designV2
              onChange={handleBrandChange}
              ref={autoSearchBrandRef}
            />
            <AutoSearchBottomSheet
              title='Model Kendaraan'
              name='model'
              data={getVehicleVariantData}
              displayKey='model_name'
              dataKey='model_code'
              showHeader
              required
              headerTitle='Model Kendaraan'
              designV2
              onChange={handleModelChange}
              ref={autoSearchModelRef}
            />
          </div>
          <BottomActionSheet
            show={showConfirmation}
            title={LANG_STRINGS.confirmation}
            onCloseSheet={() => setShowConfirmation(false)}
            backGroundColor={AgentColorPallette.darkYellow}
            showHeader
          >
            <ConfirmationContainer>
              <div className='info-icon'>
                <img
                  src={INFORMATION_NEW}
                  alt='info-icon'
                />
              </div>
              <div className='confirmation-text'>
                Sebelum melanjutkan ke tahap berikutnya, pastikan kendaraan Anda termasuk dalam kategori penggunaan kendaraan : <span className='blue-text'>Personal / Operasional Kantor </span>dan berjenis kendaraan : <span className='blue-text'>Mobil Penumpang</span>
              </div>
              <div className='confirmation-warning'>
                Ketidaksesuaian data yang dimasukkan dengan kendaraan yang sebenarnya akan mengakibatkan pembatalan pembuatan polis.
              </div>
            </ConfirmationContainer>
            <Row align='center' justify='space-between' className='padding'>
              <Button className='select-buttons reject-button' onClick={() => setShowConfirmation(false)}>Batal</Button>
              <Button className='select-buttons next-button' onClick={handleSubmit}>Lanjutkan</Button>
            </Row>
          </BottomActionSheet>
        </CriteriaPageStyle>
      </CircularLoader>
      <Footer>
        <Button className='submit-button' onClick={() => setShowConfirmation(true)} disabled={!formValues.year || Object.keys(formValues.brand_data).length === 0 || Object.keys(formValues.model_data).length === 0}>
          {LANG_STRINGS.checkPremium}
        </Button>
      </Footer>
    </Container>
  )
}

export default CriteriaPage
